#requires -Version 7
# Rebuild the bwg CPA runtime binary for v8.0.61 with the local Gemini raw
# reasoning patch applied. Production presently runs a fork binary
# (5d495e1 = official v8.0.59 + the patch) bind-mounted read-only at
# /opt/cliproxyapi/CLIProxyAPI-patched, so swapping only the compose image
# would leave the OLD binary running under the new tag. This build pins the
# upstream tag commit, proves the patched source file hashes, runs the
# translator test package, and rebuilds with the same flags as the upstream
# Dockerfile. No production file, container or credential is touched.
$ErrorActionPreference = 'Stop'
$repoRoot = Split-Path -Parent $PSScriptRoot
. (Join-Path $repoRoot 'scripts/lib/project_environment.ps1')
$python = Resolve-ProjectPython -ProjectRoot $repoRoot
$config = Resolve-LauncherConfigPath -ProjectRoot $repoRoot
$patchB64 = ''
$command = @'
set -Eeuo pipefail
umask 077
VERSION_TAG=v8.0.61
UPSTREAM_COMMIT=681ce41b6e44c45b15b79378b003909d6ba29e68
PRISTINE_TRANSLATOR_SHA=e5cc353a75e29de6b9c63a4d7b07415ead9e659826ec66cbdcb658d8d5d2f90f
PATCHED_TRANSLATOR_SHA=9d73d57f129bd339d01338ca7fe19298a88d43341a0a2b5945e954d8735e8944
GOMOD_SHA=0bde88cb0885b76451e1e000dab3ede1a2e8e37ef9800fe620d3394c1b1df941
PATCH_SHA=f6e45429c77d00b25858430284d84dfa538e30e0348dee71050d519657797134
BUILD_IMAGE=golang:1.26.10-bookworm
STAGE=/root/cpa-v8061-gemini-raw-build
SRC="$STAGE/src"
TARBALL="$STAGE/CLIProxyAPI-$VERSION_TAG.tar.gz"
TRANSLATOR=internal/translator/gemini/openai/responses/gemini_openai-responses_response.go

log() { printf '%s %s\n' "$(date -u +%FT%TZ)" "$*"; }
mkdir -m 700 -p "$STAGE"
printf '%s' '__PATCH_B64__' | base64 -d >"$STAGE/gemini-raw.patch"
[ "$(sha256sum "$STAGE/gemini-raw.patch" | cut -d' ' -f1)" = "$PATCH_SHA" ] || {
  echo PATCH_SHA_MISMATCH; exit 20;
}

if [ ! -s "$TARBALL" ]; then
  curl --fail --silent --show-error --location     --output "$TARBALL"     "https://github.com/router-for-me/CLIProxyAPI/archive/$UPSTREAM_COMMIT.tar.gz"
fi
log "SOURCE_TARBALL_SHA=$(sha256sum "$TARBALL" | cut -d' ' -f1)"
rm -rf "$SRC"
mkdir -m 700 "$SRC"
tar -xzf "$TARBALL" -C "$SRC" --strip-components=1
[ ! -s "$SRC/go.mod.patch" ]
[ "$(sha256sum "$SRC/go.mod" | cut -d' ' -f1)" = "$GOMOD_SHA" ] || {
  echo GOMOD_SHA_MISMATCH; exit 20;
}
[ "$(sha256sum "$SRC/$TRANSLATOR" | cut -d' ' -f1)" = "$PRISTINE_TRANSLATOR_SHA" ] || {
  echo PRISTINE_TRANSLATOR_SHA_MISMATCH; exit 20;
}
log 'PRISTINE_SOURCE_VERIFIED'

cd "$SRC"
git apply --check "$STAGE/gemini-raw.patch" || {
  echo PATCH_DOES_NOT_APPLY; exit 20;
}
git apply "$STAGE/gemini-raw.patch"
[ "$(sha256sum "$TRANSLATOR" | cut -d' ' -f1)" = "$PATCHED_TRANSLATOR_SHA" ] || {
  echo PATCHED_TRANSLATOR_SHA_MISMATCH; exit 20;
}
log 'PATCH_APPLIED'

docker run --rm   --cpus=2 --memory=1900m   -v "$SRC":/src -w /src   -e CGO_ENABLED=1 -e GOFLAGS=-mod=mod -e GOTOOLCHAIN=local   "$BUILD_IMAGE" bash -c '
set -Eeuo pipefail
go version
go vet ./internal/translator/gemini/openai/responses/
go test -count=1 ./internal/translator/gemini/openai/responses/
' 2>&1 | tail -20
log 'TRANSLATOR_TESTS_OK'

docker run --rm   --cpus=2 --memory=1900m   -v "$SRC":/src -w /src   -e CGO_ENABLED=1 -e GOFLAGS=-mod=mod -e GOTOOLCHAIN=local   "$BUILD_IMAGE" bash -c '
set -Eeuo pipefail
go build -buildvcs=false -trimpath   -ldflags="-s -w -X main.Version=v8.0.61 -X main.Commit=681ce41b+gemini-raw -X main.BuildDate='"$(date -u +%FT%TZ)"'"   -o /src/CLIProxyAPI.out ./cmd/server/
'
NEW="$STAGE/CLIProxyAPI-v8061-gemini-raw"
install -m 755 "$SRC/CLIProxyAPI.out" "$NEW"
NEW_SHA=$(sha256sum "$NEW" | cut -d' ' -f1)
log "BUILT_SHA=$NEW_SHA"
file "$NEW" || true
ldd "$NEW" 2>&1 | head -5 || true
sha256sum "$NEW"
'@
$command = $command.Replace('__PATCH_B64__', $patchB64)
if ($command -match '__PATCH_B64__') {
  throw 'Unfilled patch payload.'
}
Invoke-LauncherRemoteCommand -Python $python -ProjectRoot $repoRoot -Config $config -Profile bwg -Command $command -IdleTimeoutSeconds 600 -HardTimeoutSeconds 2400
